(function(){'use strict';
var DATA={"label": "Missing Value Handler - public implementations survey", "schema": {"name": "ai-build-missing-value-handler-pub", "required": ["id", "title"], "fields": {"id": "string", "title": "string", "count": "number"}}, "doc": {"id": "rec-1", "count": "three"}};

var errs=[],d=DATA.doc,s=DATA.schema;
console.log('Validating document ('+DATA.label+') against schema "'+s.name+'":');
(s.required||[]).forEach(function(f){if(!(f in d))errs.push('missing required field: '+f);});
Object.keys(s.fields||{}).forEach(function(f){if(f in d){
  var want=s.fields[f],got=Array.isArray(d[f])?'array':typeof d[f];
  if(got!==want)errs.push('field '+f+': expected '+want+', got '+got);}});
